import { JxInput, JxButton, JxToast, JxFormField } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [showToast, setShowToast] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setEmail('');
    setShowToast(true);
  };

  return (
    <div className="jx-stack jx-stack--gap-md">
      <form onSubmit={handleSubmit} className="jx-stack jx-stack--gap-sm">
        <JxFormField label="Электронная почта" htmlFor="newsletter-email">
          <JxInput
            id="newsletter-email"
            type="email"
            placeholder="you@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
        </JxFormField>

        <JxButton type="submit" variant="primary">
          Подписаться
        </JxButton>
      </form>

      {showToast && (
        <JxToast
          variant="success"
          title="Готово"
          description="Письмо с подтверждением подписки отправлено на вашу почту."
          onClose={() => setShowToast(false)}
          className="jx-toast--corner-top-right"
        />
      )}
    </div>
  );
}

